import asyncio

import httpx

CARRIERS = {"ups": "https://ups.example/api/rates", "fedex": "https://fedex.example/api/rates"}


async def fetch_rates(parcel: dict) -> dict[str, float]:
    async with httpx.AsyncClient(timeout=5.0) as client:
        responses = await asyncio.gather(
            *(client.post(url, json=parcel) for url in CARRIERS.values())
        )
    return {name: r.json()["amount"] for name, r in zip(CARRIERS, responses)}

import asyncio
import logging

from workers.notifications.queue import fetch_batch, dispatch

log = logging.getLogger(__name__)


async def poll_forever(interval: float = 2.0) -> None:
    while True:
        try:
            batch = await fetch_batch(limit=50)
            for item in batch:
                await dispatch(item)
            await asyncio.sleep(interval)
        except asyncio.CancelledError:
            log.info("poller cancelled, will keep going")
            continue
        except Exception:
            log.exception("poll iteration failed")

