import asyncio
import contextlib


async def with_keepalive(ws, handler):
    async def ping():
        while True:
            await asyncio.sleep(20)
            await ws.ping()

    pinger = asyncio.create_task(ping())
    try:
        return await handler(ws)
    finally:
        pinger.cancel()
        try:
            await pinger
        except asyncio.CancelledError:
            pass

