from fastapi import Header, HTTPException

from app.auth.tokens import decode_access_token


def parse_authorization(authorization: str = Header(default="")) -> dict:
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer":
        raise HTTPException(status_code=401, detail="expected a bearer token")
    if not token:
        raise HTTPException(status_code=401, detail="missing token")
    claims = decode_access_token(token)
    if claims.get("token_type") != "access":
        raise HTTPException(status_code=401, detail="wrong token type")
    return claims

import stripe
from django.conf import settings
from django.http import HttpResponse
from django.views.decorators.csrf import csrf_exempt

from payments.handlers import handle_event


@csrf_exempt
def stripe_webhook(request):
    signature = request.headers.get("Stripe-Signature", "")
    try:
        event = stripe.Webhook.construct_event(request.body, signature, settings.STRIPE_WEBHOOK_SECRET)
    except stripe.error.SignatureVerificationError:
        return HttpResponse(status=400)
    handle_event(event)
    return HttpResponse(status=200)

